Popup position, scale, and input are off when fractional scaling is used (125% in my case), or not showing at all if calculated position is outside parent window:

https://github.com/user-attachments/assets/655b3feb-84a0-48a7-8dca-b6fc218d88d1

Here's a quick, and probably not entirely correct fix for it (but working and should give the idea what's wrong):

```diff
diff --git a/platform/linuxbsd/wayland/wayland_thread.cpp b/platform/linuxbsd/wayland/wayland_thread.cpp
index fbce86f8c9..36dba8ace1 100644
--- a/platform/linuxbsd/wayland/wayland_thread.cpp
+++ b/platform/linuxbsd/wayland/wayland_thread.cpp
@@ -1274,6 +1274,8 @@ void WaylandThread::_xdg_popup_on_configure(void *data, struct xdg_popup *xdg_po
 	WindowState *parent = ws->wayland_thread->window_get_state(ws->parent_id);
 	ERR_FAIL_NULL(parent);
 
+	double win_scale = window_state_get_scale_factor(parent);
+
 	Point2i pos = Point2i(x, y);
 	if (parent->libdecor_frame) {
 		int translated_x = x;
@@ -1296,7 +1298,7 @@ void WaylandThread::_xdg_popup_on_configure(void *data, struct xdg_popup *xdg_po
 		Ref<WindowRectMessage> rect_msg;
 		rect_msg.instantiate();
 		rect_msg->id = ws->id;
-		rect_msg->rect = ws->rect;
+		rect_msg->rect = Rect2i(scale_vector2i(ws->rect.position, win_scale), scale_vector2i(ws->rect.size, win_scale));
 
 		ws->wayland_thread->push_message(rect_msg);
 	}
@@ -3499,6 +3501,8 @@ void WaylandThread::window_create_popup(DisplayServer::WindowID p_window_id, Dis
 	WindowState &ws = windows[p_window_id];
 	WindowState &parent = windows[p_parent_id];
 
+	double win_scale = 1.0 / window_state_get_scale_factor(&parent);
+
 	ws.id = p_window_id;
 	ws.parent_id = p_parent_id;
 	ws.registry = &registry;
@@ -3506,6 +3510,8 @@ void WaylandThread::window_create_popup(DisplayServer::WindowID p_window_id, Dis
 
 	ws.rect = p_rect;
 
+	Size2i scaled_size = scale_vector2i(p_rect.size, win_scale);
+
 	ws.wl_surface = wl_compositor_create_surface(registry.wl_compositor);
 	wl_proxy_tag_godot((struct wl_proxy *)ws.wl_surface);
 	wl_surface_add_listener(ws.wl_surface, &wl_surface_listener, &ws);
@@ -3526,7 +3532,7 @@ void WaylandThread::window_create_popup(DisplayServer::WindowID p_window_id, Dis
 	positioner_rect.size = parent.rect.size;
 	struct xdg_surface *parent_xdg_surface = parent.xdg_surface;
 
-	Point2i offset = ws.rect.position - parent.rect.position;
+	Point2i offset = scale_vector2i(p_rect.position, win_scale) - parent.rect.position;
 
 #ifdef LIBDECOR_ENABLED
 	if (!parent_xdg_surface && parent.libdecor_frame) {
@@ -3547,7 +3553,7 @@ void WaylandThread::window_create_popup(DisplayServer::WindowID p_window_id, Dis
 	ERR_FAIL_NULL(parent_xdg_surface);
 
 	struct xdg_positioner *xdg_positioner = xdg_wm_base_create_positioner(registry.xdg_wm_base);
-	xdg_positioner_set_size(xdg_positioner, ws.rect.size.width, ws.rect.size.height);
+	xdg_positioner_set_size(xdg_positioner, scaled_size.width, scaled_size.height);
